#!/usr/bin/env node
// make-design-spec.mjs — emit the design-spec artifact (Markdown) from a parsed page-map.
//
// The design-spec is the WRITTEN hand-off that execute subagents (chrome / ACM / override builders)
// read INSTEAD of conversation context (see references/design-spec.md + references/build-subagents.md §C).
// This generator pre-fills everything the Phase-2 page-map already knows (template identity, palette
// light+dark, fonts, the page/view/layout list) and leaves explicit `TODO` slots for the values that
// only settle at Phase 6 (token names, type scale, spacing) or need a human (per-section source +
// image pointers, class prefix). Dependency-free: reads JSON, writes Markdown.
//
// Usage:
//   node scripts/make-design-spec.mjs <page-map.json | -> [--out <file>]
//   node scripts/parse-html-bundle.mjs <bundle> | node scripts/make-design-spec.mjs -

import { readFileSync, writeFileSync } from 'node:fs';

const args = process.argv.slice(2);
let src = null, out = null;
for (let i = 0; i < args.length; i++) {
  if (args[i] === '--out') out = args[++i];
  else if (!src) src = args[i];
}
if (!src) {
  console.error('usage: make-design-spec.mjs <page-map.json | -> [--out <file>]');
  process.exit(2);
}

const raw = src === '-' ? readFileSync(0, 'utf8') : readFileSync(src, 'utf8');
let map;
try { map = JSON.parse(raw); }
catch (e) { console.error('cannot parse page-map JSON:', e.message); process.exit(2); }

const tpl = map.template || {};
const name = tpl.name || 'ja_<name>';
const title = tpl.title || '<Title>';
const Tpl = (title || name.replace(/^ja_/, '')).replace(/(^|\s)\S/g, s => s.toUpperCase());
const bootstrap = tpl.bootstrap || 'bs5';
const pal = (map.theme && map.theme.palette) || {};
const light = pal.light || {};
const dark = pal.dark || {};
const fonts = (map.theme && map.theme.fonts) || {};
const pages = Array.isArray(map.pages) ? map.pages : [];
const positions = Array.isArray(map.positions) ? map.positions : [];

const TODO = '`TODO`';
const v = (x) => (x ? `\`${x}\`` : TODO);

// palette rows: the 4 the parser extracts are auto-filled; the rest are TODO (read at Phase 6).
const palRow = (key, note) =>
  `| \`${key}\` | ${v(light[key])} | ${v(dark[key])} | ${note} |`;

const md = `# Design Spec — ${title} (\`${name}\`)

> **Generated by \`scripts/make-design-spec.mjs\` from the Phase-2 page-map.** This is the AUTHORITATIVE
> hand-off artifact for the execute subagents (chrome / ACM / override builders) — they read THIS, not
> the conversation. Auto-filled fields come from the page-map; **resolve every slot marker before
> dispatching any execute subagent** (the slots are the values that settle at Phase 6 or need a
> human). Contract + how-to: \`references/design-spec.md\`.

## 1. Identity
- **Machine name (\`<TPL>\`):** \`${name}\`
- **Title:** ${title}
- **Bootstrap:** ${bootstrap}
- **Dark hook (\`<DARK>\`):** ${TODO} — pin in Phase 0 (\`html.t4-dark\` or \`data-bs-theme="dark"\`; see \`css-tokenizing.md\` §3a)
- **Class prefix:** ${TODO} — e.g. \`${name.replace(/^ja_/, '')}-\` (used on every authored block/override)

## 2. Palette — light AND dark (route ALL color through these)
| token | light | dark | note |
|---|---|---|---|
${palRow('primary', 'dominant accent: CTA/link')}
${palRow('secondary', 'supporting brand')}
${palRow('body_bg', 'page surface')}
${palRow('text', 'default body text')}
| \`border\` | ${TODO} | ${TODO} | faint divider (read at Phase 6) |
| \`heading\` | ${TODO} | ${TODO} | if headings differ from body text |
| \`surface\` | ${TODO} | ${TODO} | \`.bg-light\`-style band / card bg |

> Dark MIRRORS light, every state. Remap the T4 palette-band + \`--t4-card-bg\` tokens for dark (gotchas #58/#59).

## 3. Type scale
- **Body font:** ${v(fonts.body)} · **Heading font:** ${v(fonts.heading)}
- **h1–h6 size / weight / line-height:** ${TODO} (read off rendered \`<h1>\`…\`<h6>\`, not the stylesheet — Phase 6)
- **Body size / line-height / letter-spacing:** ${TODO}
- ⚠️ **Pin these in \`etc/site/default.json\`, not just the theme JSON** — T4 generates the runtime
  \`--heading-font-*\` / \`--*-line-height\` from there; a cloned blank's Inter/600/1.3 defaults silently
  override your design otherwise (gotcha #57).

## 4. Spacing
- **Section vertical rhythm (full-width row top/bottom padding):** ${TODO}
- **Container max-width:** ${TODO} · **Gutter:** ${TODO} · **Card internal padding:** ${TODO}

## 5. T4 token taxonomy (use these names so every agent routes consistently)
- Brand: \`color_primary\`, \`color_secondary\` (\`etc/theme/default.json\` — override BS theme vars).
- Page/nav/footer: \`body_*\`, \`mainnav_*\`, \`footer_*\` (theme JSON).
- Dark companions: the \`<DARK>\` token-remap block in \`scss/darkmode.scss\` → \`css/darkmode.css\`.
- (Add any template-specific token names you introduce here so builders reuse them verbatim.)

## 6. Per-artifact source pointers (which bundle markup each builder must match, pixel-for-pixel)
Declared positions: ${positions.length ? positions.map(p => `\`${p}\``).join(', ') : TODO}

| page (source file) | view | layout | sections / blocks → source + image assets |
|---|---|---|---|
${pages.length
  ? pages.map(p => `| \`${p.file || '?'}\` | \`${p.view || '?'}\` | \`${p.layout || '—'}\` | ${TODO} |`).join('\n')
  : `| ${TODO} | | | |`}

> For each ACM block / override / chrome part a builder will author, fill the last column with the
> exact source section + the image asset (export the DARK mockup; \`media\` field, not hand-drawn SVG).

## 7. Naming conventions
- **Module titles:** \`[${Tpl}] <Page> - <Section>\` (findable in Module Manager; \`editability-standards.md\` §7).
- **Module chrome \`style\`:** T4-version/context-dependent — \`${name}-<chrome>\` (gotcha #22) OR bare \`<chrome>\` (platform-bug P75); verify which yields the chrome wrapper + \`.module-title\` on this build.
- **ACM language keys:** define in \`en-GB.tpl_${name.replace(/^ja_/, '')}.ini\` AND sync to \`<site>/language/en-GB/\`.
`;

if (out) { writeFileSync(out, md); console.error(`wrote ${out}`); }
else process.stdout.write(md);
